  1→/* ── SUPER DUPER Design System ──────────────────────────────────────
  2→ *  Native skin: ComfyUI dark theme palette
  3→ *  Accent: #4e9bcd (ComfyUI native blue)
  4→ *  Surfaces: neutral grey depth layers
  5→ *  Typography: Inter (sans) + JetBrains Mono (mono)
  6→ *  Slot colors: official ComfyUI dark theme
  7→ * ──────────────────────────────────────────────────────────────────── */
  8→
  9→@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap");
 10→
 11→/* ── Design Tokens ──────────────────────────────────────────────── */
 12→
 13→:root {
 14→  /* ComfyUI Native Surfaces */
 15→  --sd-canvas: #1e1e1e;
 16→  --sd-panel: #2b2b2b;
 17→  --sd-card: #353535;
 18→  --sd-card-hover: #3a3a3a;
 19→  --sd-elevated: #404040;
 20→  --sd-input: #1a1a1a;
 21→
 22→  /* ComfyUI Native Text */
 23→  --sd-text-primary: #ddd;
 24→  --sd-text-secondary: #aaa;
 25→  --sd-text-muted: #888;
 26→  --sd-text-accent: #ccc;
 27→
 28→  /* ComfyUI Native Borders */
 29→  --sd-border: #4e4e4e;
 30→  --sd-border-subtle: #3a3a3a;
 31→
 32→  /* Accent (ComfyUI native blue -- replaces jade green) */
 33→  --sd-accent: #4e9bcd;
 34→  --sd-accent-dim: #4e9bcd33;
 35→  --sd-accent-subtle: #4e9bcd18;
 36→
 37→  /* Keep ALL slot colors unchanged */
 38→  --sd-slot-clip: #FFD500;
 39→  --sd-slot-clip-vision: #A8DADC;
 40→  --sd-slot-conditioning: #FFA931;
 41→  --sd-slot-controlnet: #6EE7B7;
 42→  --sd-slot-image: #64B5F6;
 43→  --sd-slot-latent: #FF9CF9;
 44→  --sd-slot-mask: #81C784;
 45→  --sd-slot-model: #B39DDB;
 46→  --sd-slot-style-model: #C2FFAE;
 47→  --sd-slot-vae: #FF6E6E;
 48→  --sd-slot-noise: #B0B0B0;
 49→  --sd-slot-guider: #66FFFF;
 50→  --sd-slot-sampler: #ECB4B4;
 51→  --sd-slot-sigmas: #CDFFCD;
 52→
 53→  /* Typography */
 54→  --sd-font-sans: "Inter", "SF Pro Display", system-ui, -apple-system, sans-serif;
 55→  --sd-font-mono: "JetBrains Mono", "Fira Code", "SF Mono", "Cascadia Code", monospace;
 56→
 57→  /* Spacing */
 58→  --sd-space-xs: 4px;
 59→  --sd-space-sm: 6px;
 60→  --sd-space-md: 8px;
 61→  --sd-space-lg: 12px;
 62→  --sd-space-xl: 16px;
 63→
 64→  --sd-transition: 150ms ease;
 65→}
 66→
 67→/* ── Layout Shell ───────────────────────────────────────────────── */
 68→
 69→.sd-header {
 70→  display: flex;
 71→  align-items: center;
 72→  justify-content: space-between;
 73→  padding: var(--sd-space-lg) var(--sd-space-xl);
 74→  font-family: var(--sd-font-sans);
 75→  font-size: 13px;
 76→  font-weight: 500;
 77→  letter-spacing: 0.02em;
 78→  color: var(--sd-text-primary);
 79→  border-bottom: 1px solid var(--sd-border-subtle);
 80→  background: var(--sd-panel);
 81→  flex-shrink: 0;
 82→}
 83→
 84→.sd-header__title {
 85→  flex: 1;
 86→}
 87→
 88→.sd-header__status {
 89→  font-family: var(--sd-font-mono);
 90→  font-size: 10px;
 91→  font-weight: 400;
 92→  color: var(--sd-text-muted);
 93→  text-transform: uppercase;
 94→  letter-spacing: 0.06em;
 95→}
 96→
 97→.sd-header__status--connecting {
 98→  color: #e6a23c;
 99→}
100→
101→.sd-header__status--disconnected {
102→  color: #f56c6c;
103→}
104→
105→/* ── Stage Indicator ────────────────────────────────────────────── */
106→
107→.sd-stage-bar {
108→  display: flex;
109→  align-items: center;
110→  gap: var(--sd-space-md);
111→  padding: var(--sd-space-sm) var(--sd-space-xl);
112→  background: var(--sd-accent-subtle);
113→  border-bottom: 1px solid var(--sd-border-subtle);
114→  flex-shrink: 0;
115→  font-size: 12px;
116→  animation: sd-pulse 1.5s ease-in-out infinite;
117→}
118→
119→.sd-stage__label {
120→  font-family: var(--sd-font-mono);
121→  color: var(--sd-accent);
122→  font-weight: 600;
123→  font-size: 10px;
124→  letter-spacing: 0.06em;
125→  text-transform: uppercase;
126→}
127→
128→.sd-stage__detail {
129→  font-family: var(--sd-font-sans);
130→  color: var(--sd-text-muted);
131→  font-size: 11px;
132→}
133→
134→@keyframes sd-pulse {
135→  0%, 100% { opacity: 1; }
136→  50% { opacity: 0.6; }
137→}
138→
139→/* ── Messages Area ──────────────────────────────────────────────── */
140→
141→.sd-messages {
142→  flex: 1;
143→  overflow-y: auto;
144→  padding: var(--sd-space-lg);
145→  display: flex;
146→  flex-direction: column;
147→  gap: var(--sd-space-md);
148→  background: var(--sd-canvas);
149→}
150→
151→/* ── Message Bubbles ────────────────────────────────────────────── */
152→
153→.sd-message {
154→  display: flex;
155→  flex-direction: column;
156→  gap: 2px;
157→  padding: var(--sd-space-md) 10px;
158→  border-radius: 6px;
159→  font-family: var(--sd-font-sans);
160→  font-size: 12px;
161→  line-height: 1.5;
162→  word-wrap: break-word;
163→}
164→
165→.sd-message--user {
166→  background: var(--sd-card);
167→  align-self: flex-end;
168→  max-width: 90%;
169→}
170→
171→.sd-message--agent {
172→  background: var(--sd-panel);
173→  align-self: flex-start;
174→  max-width: 95%;
175→}
176→
177→.sd-message--system {
178→  background: transparent;
179→  color: var(--sd-text-muted);
180→  font-style: italic;
181→  font-size: 11px;
182→  align-self: center;
183→}
184→
185→.sd-message__label {
186→  font-family: var(--sd-font-mono);
187→  font-size: 10px;
188→  font-weight: 400;
189→  color: var(--sd-text-muted);
190→  text-transform: uppercase;
191→  letter-spacing: 0.06em;
192→}
193→
194→.sd-message--user .sd-message__label {
195→  color: var(--sd-text-accent);
196→}
197→
198→.sd-message--agent .sd-message__label {
199→  color: var(--sd-accent);
200→}
201→
202→.sd-message__body {
203→  color: var(--sd-text-secondary);
204→}
205→
206→.sd-message--user .sd-message__body {
207→  color: var(--sd-text-primary);
208→}
209→
210→.sd-message--system .sd-message__body {
211→  color: var(--sd-text-muted);
212→}
213→
214→/* ── Text Rendering Classes ─────────────────────────────────────── */
215→
216→.sd-text-body {
217→  font-family: var(--sd-font-sans);
218→  font-size: 12px;
219→  color: var(--sd-text-secondary);
220→  line-height: 1.5;
221→}
222→
223→.sd-text-body p {
224→  margin: 0 0 var(--sd-space-md) 0;
225→}
226→
227→.sd-text-body p:last-child {
228→  margin-bottom: 0;
229→}
230→
231→.sd-code-inline {
232→  font-family: var(--sd-font-mono);
233→  font-size: 11px;
234→  background: var(--sd-elevated);
235→  color: var(--sd-text-accent);
236→  padding: 1px 5px;
237→  border-radius: 3px;
238→  letter-spacing: 0.01em;
239→}
240→
241→.sd-code-block {
242→  font-family: var(--sd-font-mono);
243→  font-size: 11px;
244→  line-height: 1.5;
245→  background: var(--sd-input);
246→  color: var(--sd-text-primary);
247→  padding: var(--sd-space-md) var(--sd-space-lg);
248→  border-radius: 4px;
249→  border: 1px solid var(--sd-border-subtle);
250→  margin: var(--sd-space-md) 0;
251→  overflow-x: auto;
252→  white-space: pre;
253→}
254→
255→.sd-text-bold {
256→  font-weight: 600;
257→  color: var(--sd-text-primary);
258→}
259→
260→/* ── Typing Indicator ───────────────────────────────────────────── */
261→
262→.sd-typing {
263→  display: inline-flex;
264→  align-items: center;
265→  gap: 4px;
266→  padding: 4px 0;
267→}
268→
269→.sd-typing__dot {
270→  width: 5px;
271→  height: 5px;
272→  border-radius: 50%;
273→  background: var(--sd-accent);
274→  animation: sd-typing-pulse 1.2s ease-in-out infinite;
275→}
276→
277→.sd-typing__dot:nth-child(2) {
278→  animation-delay: 0.15s;
279→}
280→
281→.sd-typing__dot:nth-child(3) {
282→  animation-delay: 0.3s;
283→}
284→
285→@keyframes sd-typing-pulse {
286→  0%, 60%, 100% { opacity: 0.3; transform: scale(0.8); }
287→  30% { opacity: 1; transform: scale(1); }
288→}
289→
290→/* ── Input Bar ──────────────────────────────────────────────────── */
291→
292→.sd-input-bar {
293→  display: flex;
294→  gap: var(--sd-space-sm);
295→  padding: 10px var(--sd-space-lg);
296→  border-top: 1px solid var(--sd-border);
297→  background: var(--sd-panel);
298→  flex-shrink: 0;
299→}
300→
301→.sd-input {
302→  flex: 1;
303→  background: var(--sd-input);
304→  border: 1px solid var(--sd-border);
305→  border-radius: 6px;
306→  padding: var(--sd-space-md) 10px;
307→  color: var(--sd-text-primary);
308→  font-family: var(--sd-font-sans);
309→  font-size: 12px;
310→  outline: none;
311→  transition: border-color var(--sd-transition);
312→}
313→
314→.sd-input:focus {
315→  border-color: var(--sd-accent);
316→}
317→
318→.sd-input::placeholder {
319→  color: var(--sd-text-muted);
320→}
321→
322→.sd-send-btn {
323→  background: var(--sd-accent);
324→  color: #1a1a1a;
325→  border: none;
326→  border-radius: 6px;
327→  padding: var(--sd-space-md) 14px;
328→  font-family: var(--sd-font-sans);
329→  font-size: 12px;
330→  font-weight: 600;
331→  cursor: pointer;
332→  transition: background var(--sd-transition), opacity var(--sd-transition);
333→  flex-shrink: 0;
334→}
335→
336→.sd-send-btn:hover {
337→  opacity: 0.9;
338→}
339→
340→.sd-send-btn:active {
341→  opacity: 0.8;
342→}
343→
344→.sd-send-btn:disabled {
345→  background: var(--sd-elevated);
346→  color: var(--sd-text-muted);
347→  cursor: not-allowed;
348→  opacity: 1;
349→}
350→
351→/* ── Scrollbar ──────────────────────────────────────────────────── */
352→
353→.sd-messages::-webkit-scrollbar {
354→  width: 3px;
355→}
356→
357→.sd-messages::-webkit-scrollbar-track {
358→  background: transparent;
359→}
360→
361→.sd-messages::-webkit-scrollbar-thumb {
362→  background: var(--sd-border);
363→  border-radius: 2px;
364→}
365→
366→.sd-messages::-webkit-scrollbar-thumb:hover {
367→  background: var(--sd-text-muted);
368→}
369→
370→/* ── Panel Components ───────────────────────────────────────────── */
371→
372→/* Panel container */
373→.sd-panel {
374→  background: var(--sd-panel);
375→  border-radius: 6px;
376→  border: 1px solid var(--sd-border-subtle);
377→  overflow: hidden;
378→  margin: var(--sd-space-xs) 0;
379→  max-width: 100%;
380→}
381→
382→/* Panel header */
383→.sd-panel__header {
384→  padding: var(--sd-space-xl) 14px 14px;
385→}
386→
387→.sd-panel__label-row {
388→  display: flex;
389→  align-items: center;
390→  justify-content: space-between;
391→  margin-bottom: var(--sd-space-md);
392→}
393→
394→.sd-panel__label {
395→  font-family: var(--sd-font-mono);
396→  font-size: 10px;
397→  font-weight: 400;
398→  color: var(--sd-text-muted);
399→  text-transform: uppercase;
400→  letter-spacing: 0.06em;
401→}
402→
403→.sd-panel__badge {
404→  font-family: var(--sd-font-mono);
405→  font-size: 10px;
406→  font-weight: 400;
407→  color: var(--sd-accent);
408→  background: var(--sd-accent-subtle);
409→  padding: 2px 8px;
410→  border-radius: 3px;
411→  letter-spacing: 0.01em;
412→}
413→
414→.sd-panel__title {
415→  font-family: var(--sd-font-sans);
416→  font-size: 16px;
417→  font-weight: 600;
418→  color: var(--sd-text-primary);
419→  letter-spacing: -0.02em;
420→  margin-bottom: var(--sd-space-sm);
421→  line-height: 1.3;
422→}
423→
424→.sd-panel__summary {
425→  font-family: var(--sd-font-sans);
426→  font-size: 12px;
427→  color: var(--sd-text-secondary);
428→  line-height: 1.5;
429→  margin-bottom: var(--sd-space-lg);
430→}
431→
432→.sd-panel__stats {
433→  display: flex;
434→  gap: var(--sd-space-xl);
435→}
436→
437→.sd-panel__stat {
438→  display: flex;
439→  flex-direction: column;
440→  gap: 1px;
441→}
442→
443→.sd-panel__stat-value {
444→  font-family: var(--sd-font-mono);
445→  font-size: 14px;
446→  font-weight: 600;
447→  color: var(--sd-text-primary);
448→}
449→
450→.sd-panel__stat-label {
451→  font-family: var(--sd-font-sans);
452→  font-size: 10px;
453→  color: var(--sd-text-muted);
454→}
455→
456→/* Collapsible section */
457→.sd-section {
458→  border-top: 1px solid var(--sd-border-subtle);
459→}
460→
461→.sd-section__trigger {
462→  display: flex;
463→  align-items: center;
464→  width: 100%;
465→  padding: 10px 14px;
466→  background: none;
467→  border: none;
468→  cursor: pointer;
469→  color: var(--sd-text-primary);
470→  font-family: var(--sd-font-sans);
471→  font-size: 12px;
472→  font-weight: 500;
473→  letter-spacing: 0.01em;
474→  text-align: left;
475→  gap: var(--sd-space-md);
476→  transition: background var(--sd-transition);
477→}
478→
479→.sd-section__trigger:hover {
480→  background: var(--sd-card);
481→}
482→
483→.sd-section__dot {
484→  width: 5px;
485→  height: 5px;
486→  border-radius: 50%;
487→  flex-shrink: 0;
488→}
489→
490→.sd-section__title {
491→  flex: 1;
492→}
493→
494→.sd-section__count {
495→  font-family: var(--sd-font-mono);
496→  font-size: 10px;
497→  color: var(--sd-text-muted);
498→  letter-spacing: 0.01em;
499→}
500→
501→.sd-section__chevron {
502→  font-size: 10px;
503→  color: var(--sd-text-muted);
504→  transition: transform var(--sd-transition);
505→  flex-shrink: 0;
506→}
507→
508→.sd-section--open > .sd-section__trigger .sd-section__chevron {
509→  transform: rotate(90deg);
510→}
511→
512→.sd-section__body {
513→  padding: 0 14px 12px;
514→  display: none;
515→}
516→
517→.sd-section--open > .sd-section__body {
518→  display: block;
519→}
520→
