523→  display: inline-flex;
524→  align-items: center;
525→  gap: var(--sd-space-xs);
526→  padding: 2px 8px 2px 6px;
527→  border-radius: 3px;
528→  font-family: var(--sd-font-mono);
529→  font-size: 11px;
530→  letter-spacing: 0.01em;
531→  margin: 0 var(--sd-space-xs) var(--sd-space-xs) 0;
532→}
533→
534→.sd-slot-tag__dot {
535→  width: 5px;
536→  height: 5px;
537→  border-radius: 50%;
538→  flex-shrink: 0;
539→}
540→
541→/* Flow chain */
542→.sd-flow-chain {
543→  display: flex;
544→  flex-wrap: wrap;
545→  align-items: center;
546→  gap: 2px;
547→  padding: var(--sd-space-xs) 0;
548→}
549→
550→.sd-flow-chain__label {
551→  font-family: var(--sd-font-mono);
552→  font-size: 10px;
553→  color: var(--sd-text-muted);
